import { Avatar } from '@refy-design/web';
import { PersonCell } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof PersonCell>, 'name' | 'secondary' | 'size'> = {
    name: 'Marina Salgado',
    secondary: 'marina@example.com',
    size: 'md',
  };
  return (
    <PersonCell
      {...args}
      avatar={<Avatar size="md" initials="MS" seed="Marina Salgado" />}
    />
  );
}

